public void new()
{
    vehicleListInternal = new List(Types::Class);
}

[SysAppCollection(classStr(FMVehicleListPageItem), "Vehicle list")]
public List vehicleList(List _value=vehicleListInternal)
{
    vehicleListInternal = _value;
    return vehicleListInternal;
}

public static FMVehicleListPage getAllVehicles(SysAppEntityContext _entityContext, List _filterContextList)
{
    FMVehicle vehicleTable;
    FMVehicleModel vehicleModel;   
    FMVehicleListPage vehicleListPage = new FMVehicleListPage();

    while select * from vehicleTable
        join vehicleModel
        order by vehicleTable.VehicleId
        where vehicleTable.VehicleModel == vehicleModel.RecId
    {
        FMVehicleListPageItem vehicleItem = new FMVehicleListPageItem();
        vehicleItem.populate(vehicleTable, vehicleModel);

        vehicleListPage.vehicleList().addEnd(vehicleItem);
    }

    return vehicleListPage;
}
